<?php
declare(strict_types=1);$root='/var/www/html';$zip='/tmp/wc.zip';file_put_contents($zip,file_get_contents('https://downloads.wordpress.org/plugin/woocommerce.9.7.0.zip'));$z=new ZipArchive();$z->open($zip);$z->extractTo($root.'/wp-content/plugins');$z->close();require $root.'/wp-load.php';require_once ABSPATH.'wp-admin/includes/plugin.php';activate_plugin('woocommerce/woocommerce.php');activate_plugin('ferreta-core/ferreta-core.php');switch_theme('ferreta');foreach(['shop'=>'Каталог','cart'=>'Кошик','checkout'=>'Оформлення','myaccount'=>'Кабінет']as$k=>$title){$id=wc_get_page_id($k);if($id<1){$id=wp_insert_post(['post_title'=>$title,'post_status'=>'publish','post_type'=>'page','post_content'=>'['.($k==='myaccount'?'woocommerce_my_account':"woocommerce_$k").']']);update_option("woocommerce_{$k}_page_id",$id);}}flush_rewrite_rules();echo 'ready';
